CREATE EXTENSION IF NOT EXISTS vector;
CREATE TABLE IF NOT EXISTS users(id text PRIMARY KEY,name text NOT NULL,role text NOT NULL CHECK(role IN ('employee','operator')),location text NOT NULL,device text NOT NULL,scope text NOT NULL,external_account text);
CREATE TABLE IF NOT EXISTS reports(id uuid PRIMARY KEY,owner_id text NOT NULL REFERENCES users(id),submission_key uuid NOT NULL,summary text NOT NULL,state text NOT NULL,decision jsonb NOT NULL,clarifications int NOT NULL DEFAULT 0,offered jsonb NOT NULL DEFAULT '[]',attempted jsonb NOT NULL DEFAULT '[]',provider_key text,provider_url text,provider_status text,provider_team text,provider_priority text,synced_at timestamptz,acknowledged_at timestamptz,related_id text,mode text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(owner_id,submission_key));
CREATE TABLE IF NOT EXISTS messages(id uuid PRIMARY KEY,report_id uuid NOT NULL REFERENCES reports(id) ON DELETE CASCADE,role text NOT NULL,body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sources(id text PRIMARY KEY,kind text NOT NULL,title text NOT NULL,body text NOT NULL,service text NOT NULL,visibility text NOT NULL DEFAULT 'all',location text,status text NOT NULL DEFAULT 'approved',metadata jsonb NOT NULL DEFAULT '{}',embedding vector(256),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS source_search ON sources USING gin(to_tsvector('english',title||' '||body));
CREATE TABLE IF NOT EXISTS context_snapshots(id uuid PRIMARY KEY,report_id uuid NOT NULL REFERENCES reports(id) ON DELETE CASCADE,context jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS decisions(id uuid PRIMARY KEY,report_id uuid NOT NULL REFERENCES reports(id) ON DELETE CASCADE,decision jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS connector_operations(id uuid PRIMARY KEY,report_id uuid NOT NULL REFERENCES reports(id) ON DELETE CASCADE,operation_key text NOT NULL UNIQUE,kind text NOT NULL,state text NOT NULL,payload jsonb NOT NULL,payload_hash text NOT NULL,external_key text,attempts int NOT NULL DEFAULT 0,last_error text,next_attempt_at timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS operator_events(id uuid PRIMARY KEY,report_id uuid NOT NULL REFERENCES reports(id) ON DELETE CASCADE,actor_id text REFERENCES users(id),kind text NOT NULL,detail jsonb NOT NULL,dedupe_key text UNIQUE,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS action_receipts(owner_id text NOT NULL,submission_key uuid NOT NULL,report_id uuid NOT NULL REFERENCES reports(id) ON DELETE CASCADE,PRIMARY KEY(owner_id,submission_key));
CREATE TABLE IF NOT EXISTS demo_tickets(key text PRIMARY KEY,marker text UNIQUE NOT NULL,summary text NOT NULL,status text NOT NULL DEFAULT 'Open',team text NOT NULL,priority text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE SEQUENCE IF NOT EXISTS demo_ticket_seq START 101;
CREATE TABLE IF NOT EXISTS worker_health(id text PRIMARY KEY,last_seen timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),expires_at timestamptz NOT NULL);
